import urllib.request, re, json
url='https://www.youtube.com/watch?v=94kAIpRnhcY'
html=urllib.request.urlopen(url).read().decode('utf-8')

def extract_json(varname):
    idx = html.find(varname)
    if idx==-1:
        return None
    # find first '{' after varname
    start = html.find('{', idx)
    if start==-1:
        return None
    # bracket matching
    depth=0
    for i in range(start, len(html)):
        if html[i]=='{':
            depth+=1
        elif html[i]=='}':
            depth-=1
            if depth==0:
                end=i+1
                return html[start:end]
    return None

def find_chapters(obj):
    if isinstance(obj, dict):
        if 'chapters' in obj:
            return obj['chapters']
        for v in obj.values():
            res = find_chapters(v)
            if res is not None:
                return res
    elif isinstance(obj, list):
        for v in obj:
            res = find_chapters(v)
            if res is not None:
                return res
    return None

for var in ['ytInitialPlayerResponse', 'ytInitialData']:
    js = extract_json(var)
    print(var, 'found', js is not None)
    if js:
        try:
            data=json.loads(js)
        except Exception as e:
            print('json load error', e)
            continue
        chapters = find_chapters(data)
        print('chapters found', chapters is not None)
        if chapters:
            print('chapters type', type(chapters), 'len', len(chapters))
            print(json.dumps(chapters[:2], indent=2))
            break
