import urllib.request, json
url='https://www.youtube.com/watch?v=94kAIpRnhcY'
html=urllib.request.urlopen(url).read().decode('utf-8')

def extract_json(varname):
    idx = html.find(varname)
    if idx==-1:
        return None
    start = html.find('{', idx)
    if start==-1:
        return None
    depth=0
    for i in range(start, len(html)):
        if html[i]=='{':
            depth+=1
        elif html[i]=='}':
            depth-=1
            if depth==0:
                return html[start:i+1]
    return None

def find_chapters(obj):
    if isinstance(obj, dict):
        if 'chapters' in obj:
            return obj['chapters']
        for v in obj.values():
            res = find_chapters(v)
            if res is not None:
                return res
    elif isinstance(obj, list):
        for v in obj:
            res = find_chapters(v)
            if res is not None:
                return res
    return None

js = extract_json('ytInitialData')
if not js:
    raise SystemExit('ytInitialData not found')
obj = json.loads(js)
chapters = find_chapters(obj)
print('chapters count', len(chapters))
for ch in chapters:
    r = ch.get('chapterRenderer', {})
    title = r.get('title', {}).get('simpleText')
    t_ms = r.get('timeRangeStartMillis')
    print(title, t_ms/1000)
